sys_variable_value.value:
(function execute(inputs, outputs) {
    var helper = new x_1815796_itsmgr_0.AiBotHelper();
    
    var idList = inputs.attachment_ids.split(',');
    
    var results = helper.sendMultipleAttachments(idList);
    
    outputs.upload_summary = JSON.stringify(results);
    
    var successIds = [];
    results.forEach(function(res) {
        if (res.file_id) successIds.push(res.file_id);
    });
    outputs.successful_file_ids = successIds.join(',');

})(inputs, outputs);

